        word = m.group("word")
        defn = m.group("def")
        # determine polarity from defn start and tail
        neg = False
        # tails: in no context, in certain contexts, in any context with may not already in defn
        if "in no context" in tail:
            neg = True
        if defn.lower().startswith("in no context "):
            neg = True
            defn = defn[len("In no context "):] if defn.startswith("In no context ") else defn[len("in no context "):]
        # "may not be an appropriate" - the regex used "may be" only... handle may not separately
        return ("typeA", word.lower(), defn, neg, tail, s)

    m = re.match(r"^(?P<def>.+?) may not be an appropriate definition of (?P<word>[A-Za-z0-9-]+)(?P<tail>.*)$", s)
