    m = re.match(r"^No (?P<word>[A-Za-z0-9-]+) (?P<mid>.*)$", s)
    if m:
        return ("no", m.group("word").lower(), m.group("mid"), True, "", s)

    # A WORD is never / may be / is commonly / is not / never
    m = re.match(r"^An? (?P<word>[A-Za-z0-9-]+) (?P<mid>.*)$", s)
